    const f = new Intl.DateTimeFormat(HG_LOC(), Object.assign({ hour: '2-digit', minute: '2-digit' }, o)), E = (this._ev || []).filter((e) => e.ad || e.en > now).slice(0, 4);
    if (!E.length) { box.hidden = true; return; }
